#include <cstdio>
#include <cstring>
#include <cmath>
#include <cstdlib>
#include <vector>
#include <string>
#include <algorithm>
#include <queue>
#include <stack>
#include <deque>
#include <map>
#include <set>
#include <unordered_map>
#include <unordered_set>
#include <functional>
#include <numeric>
#include <sstream>
#include <iostream>
using namespace std;
int main(){string num;int k;cin>>num>>k;
string st;
for(char c:num){while(k>0&&!st.empty()&&st.back()>c){st.pop_back();--k;}st.push_back(c);}
while(k>0&&!st.empty()){st.pop_back();--k;}
size_t i=0;while(i<st.size()&&st[i]=='0')++i;
string r=st.substr(i);
printf("%s\n",r.empty()?"0":r.c_str());return 0;}

